/* Set the CSS variables directly in place of the Tailwind value utilities, such as style="--scroll-fade-size: 2rem". */

/* =============== Scroll fade =============== */
@property --scroll-fade-t {
	syntax: "<length-percentage>";
	inherits: false;
	initial-value: 0px;
}
@property --scroll-fade-b {
	syntax: "<length-percentage>";
	inherits: false;
	initial-value: 0px;
}
@property --scroll-fade-s {
	syntax: "<length-percentage>";
	inherits: false;
	initial-value: 0px;
}
@property --scroll-fade-e {
	syntax: "<length-percentage>";
	inherits: false;
	initial-value: 0px;
}
@property --scroll-fade-mask {
	syntax: "*";
	inherits: false;
}

/* Fade sizes default to min(12%, 2.5rem) (40px); reveal distances default to 6rem (96px). */
@keyframes scroll-fade-reveal-t {
	from {
		--scroll-fade-t: 0px;
	}
	to {
		--scroll-fade-t: var(--_scroll-fade-size-t, var(--scroll-fade-size, min(12%, 2.5rem)));
	}
}
@keyframes scroll-fade-reveal-b {
	from {
		--scroll-fade-b: var(--_scroll-fade-size-b, var(--scroll-fade-size, min(12%, 2.5rem)));
	}
	to {
		--scroll-fade-b: 0px;
	}
}
@keyframes scroll-fade-reveal-s {
	from {
		--scroll-fade-s: 0px;
	}
	to {
		--scroll-fade-s: var(--_scroll-fade-size-s, var(--scroll-fade-size, min(12%, 2.5rem)));
	}
}
@keyframes scroll-fade-reveal-e {
	from {
		--scroll-fade-e: var(--_scroll-fade-size-e, var(--scroll-fade-size, min(12%, 2.5rem)));
	}
	to {
		--scroll-fade-e: 0px;
	}
}

/* Shared mask setup */
.scroll-fade,
.scroll-fade-y,
.scroll-fade-x,
.scroll-fade-t,
.scroll-fade-b,
.scroll-fade-l,
.scroll-fade-r,
.scroll-fade-s,
.scroll-fade-e {
	-webkit-mask-repeat: no-repeat;
	mask-repeat: no-repeat;
	-webkit-mask-composite: source-in;
	mask-composite: intersect;
}

/* Block axis (top and bottom) */
.scroll-fade,
.scroll-fade-y {
	--_scroll-fade-size-t: var(--scroll-fade-t-size, var(--scroll-fade-size, min(12%, 2.5rem)));
	--_scroll-fade-size-b: var(--scroll-fade-b-size, var(--scroll-fade-size, min(12%, 2.5rem)));
	--scroll-fade-block: linear-gradient(to bottom, transparent 0, #000 var(--scroll-fade-t, 0px), #000 calc(100% - var(--scroll-fade-b, 0px)), transparent 100%);
	-webkit-mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
	mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
}

/* Inline axis (start and end) */
.scroll-fade-x {
	--_scroll-fade-size-s: var(--scroll-fade-s-size, var(--scroll-fade-size, min(12%, 2.5rem)));
	--_scroll-fade-size-e: var(--scroll-fade-e-size, var(--scroll-fade-size, min(12%, 2.5rem)));
	--scroll-fade-inline: linear-gradient(to right, transparent 0, #000 var(--scroll-fade-s, 0px), #000 calc(100% - var(--scroll-fade-e, 0px)), transparent 100%);
	-webkit-mask-image: var(--scroll-fade-mask, var(--scroll-fade-inline));
	mask-image: var(--scroll-fade-mask, var(--scroll-fade-inline));
}
.scroll-fade-x:where([dir="rtl"], [dir="rtl"] *) {
	--scroll-fade-inline: linear-gradient(to left, transparent 0, #000 var(--scroll-fade-s, 0px), #000 calc(100% - var(--scroll-fade-e, 0px)), transparent 100%);
}

/* Single edges */
.scroll-fade-t {
	--_scroll-fade-size-t: var(--scroll-fade-t-size, var(--scroll-fade-size, min(12%, 2.5rem)));
	--scroll-fade-mask: linear-gradient(to bottom, transparent 0, #000 var(--scroll-fade-t, 0px), #000 100%);
	-webkit-mask-image: var(--scroll-fade-mask);
	mask-image: var(--scroll-fade-mask);
}
