		animation-fill-mode: both;
		animation-timeline: scroll(self inline), scroll(self inline);
		animation-range:
			0 var(--scroll-fade-reveal, 6rem),
			calc(100% - var(--scroll-fade-reveal, 6rem)) 100%;
	}
	.scroll-fade-t {
		animation: scroll-fade-reveal-t 1ms ease-in-out;
		animation-fill-mode: both;
		animation-timeline: scroll(self y);
		animation-range: 0 var(--scroll-fade-reveal, 6rem);
	}
	.scroll-fade-b {
		animation: scroll-fade-reveal-b 1ms ease-in-out;
		animation-fill-mode: both;
		animation-timeline: scroll(self y);
		animation-range: calc(100% - var(--scroll-fade-reveal, 6rem)) 100%;
	}
	.scroll-fade-l {
		animation: scroll-fade-reveal-s 1ms ease-in-out;
		animation-fill-mode: both;
		animation-timeline: scroll(self x);
		animation-range: 0 var(--scroll-fade-reveal, 6rem);
	}
	.scroll-fade-r {
		animation: scroll-fade-reveal-e 1ms ease-in-out;
		animation-fill-mode: both;
		animation-timeline: scroll(self x);
		animation-range: calc(100% - var(--scroll-fade-reveal, 6rem)) 100%;
	}
	.scroll-fade-s {
		animation: scroll-fade-reveal-s 1ms ease-in-out;
		animation-fill-mode: both;
		animation-timeline: scroll(self inline);
		animation-range: 0 var(--scroll-fade-reveal, 6rem);
	}
	.scroll-fade-e {
		animation: scroll-fade-reveal-e 1ms ease-in-out;
		animation-fill-mode: both;
		animation-timeline: scroll(self inline);
		animation-range: calc(100% - var(--scroll-fade-reveal, 6rem)) 100%;
	}
}

/* Without scroll-driven animations, keep every fade visible. */
@supports not (animation-timeline: scroll()) {
	.scroll-fade,
	.scroll-fade-y,
	.scroll-fade-t {
		--scroll-fade-t: var(--_scroll-fade-size-t);
	}
	.scroll-fade,
	.scroll-fade-y,
	.scroll-fade-b {
		--scroll-fade-b: var(--_scroll-fade-size-b);
	}
	.scroll-fade-x,
	.scroll-fade-l,
	.scroll-fade-s {
		--scroll-fade-s: var(--_scroll-fade-size-s);
	}
	.scroll-fade-x,
	.scroll-fade-r,
